.darma-loader-darma-b14-scissors-cut { --accent: var(--loader-color, #94a3b8); --accent-2: var(--loader-secondary-color, #e11d48); --pivot: calc(var(--loader-size, 112px) * .3); width: var(--loader-size, 112px); height: calc(var(--loader-size, 112px) * .58); position: relative; }
.darma-loader-darma-b14-scissors-cut::before { content: ''; position: absolute; top: calc(50% - 1.5px); left: 0; width: 100%; height: 3px; background: repeating-linear-gradient(90deg, color-mix(in srgb, #000 26%, var(--accent-2)) 0 calc(var(--loader-size, 112px) * .045), transparent calc(var(--loader-size, 112px) * .045) calc(var(--loader-size, 112px) * .085)); }
.darma-loader-darma-b14-scissors-cut::after { content: ''; position: absolute; z-index: 3; top: calc(50% - var(--loader-size, 112px) * .022); left: calc(8% + var(--pivot) - var(--loader-size, 112px) * .022); width: calc(var(--loader-size, 112px) * .044); height: calc(var(--loader-size, 112px) * .044); border-radius: 50%; background: color-mix(in srgb, #000 45%, var(--accent)); }
.darma-loader-darma-b14-scissors-cut span { position: absolute; left: 8%; top: calc(50% - var(--loader-size, 112px) * .045); width: 84%; height: calc(var(--loader-size, 112px) * .09); transform-origin: var(--pivot) center; }
.darma-loader-darma-b14-scissors-cut span::before { content: ''; position: absolute; inset: 0; clip-path: polygon(0 42%, 30% 16%, 100% 44%, 100% 56%, 30% 84%, 0 58%); }
.darma-loader-darma-b14-scissors-cut span::after { content: ''; position: absolute; top: 50%; left: calc(var(--loader-size, 112px) * -.01); width: calc(var(--loader-size, 112px) * .15); height: calc(var(--loader-size, 112px) * .15); border-radius: 50%; border: calc(var(--loader-size, 112px) * .028) solid var(--accent-2); }
.darma-loader-darma-b14-scissors-cut span:nth-child(1) { animation: darma-loader-darma-b14-scissors-cut-snip-top calc(var(--loader-speed, 1s) * 1.3) ease-in-out infinite; }
.darma-loader-darma-b14-scissors-cut span:nth-child(1)::before { background: linear-gradient(180deg, color-mix(in srgb, #fff 66%, var(--accent)), var(--accent)); }
.darma-loader-darma-b14-scissors-cut span:nth-child(1)::after { margin-top: calc(var(--loader-size, 112px) * -.155); }
.darma-loader-darma-b14-scissors-cut span:nth-child(2) { animation: darma-loader-darma-b14-scissors-cut-snip-bottom calc(var(--loader-speed, 1s) * 1.3) ease-in-out infinite; }
.darma-loader-darma-b14-scissors-cut span:nth-child(2)::before { background: linear-gradient(180deg, var(--accent), color-mix(in srgb, #000 26%, var(--accent))); }
.darma-loader-darma-b14-scissors-cut span:nth-child(2)::after { margin-top: calc(var(--loader-size, 112px) * .005); }
@keyframes darma-loader-darma-b14-scissors-cut-snip-top { 0%, 100% { transform: rotate(-17deg); } 50% { transform: rotate(-3deg); } }
@keyframes darma-loader-darma-b14-scissors-cut-snip-bottom { 0%, 100% { transform: rotate(17deg); } 50% { transform: rotate(3deg); } }

